import com.comsol.model.*;import com.comsol.model.util.*;
public class ExportDriveOpticalSweep{public static void main(String[]a)throws Exception{ModelUtil.initStandalone(true);Model m=ModelUtil.load("m","D:\\comsol_ao_run\\convergence\\Wap_6um_driven_coupled_fine_target.mph");try{String[]ds=m.result().dataset().tags();String d=ds[ds.length-1];m.result().numerical().create("evalOF","EvalGlobal");m.result().numerical("evalOF").set("data",d);m.result().numerical("evalOF").set("looplevelinput",new String[]{"all"});m.result().numerical("evalOF").set("expr",new String[]{"freq"});double[][]f=m.result().numerical("evalOF").getReal();for(int j=0;j<f[0].length;j++){String tag="expOS"+(j+1);m.result().export().create(tag,"Data");m.result().export(tag).set("data",d);m.result().export(tag).set("looplevelinput",new String[]{"manual"});m.result().export(tag).set("looplevel",new String[]{Integer.toString(j+1)});m.result().export(tag).set("expr",new String[]{"x","y","z","real(solid.eXX)","imag(solid.eXX)","real(solid.eYY)","imag(solid.eYY)","real(solid.eZZ)","imag(solid.eZZ)"});String file=String.format(java.util.Locale.US,"D:\\comsol_ao_run\\convergence\\mode_match\\driven_strain_%02d_%.6fGHz.csv",j+1,f[0][j]/1e9);m.result().export(tag).set("filename",file);m.result().export(tag).set("header","on");m.result().export(tag).set("sort","on");m.result().export(tag).run();System.out.println("EXPORTED "+file);}}catch(Throwable t){t.printStackTrace(System.out);}finally{ModelUtil.disconnect();}}}
